<div class="page-header"><div><p class="eyebrow">ACCESS CONTROL</p><h1>User accounts</h1><p>Accounts are assigned to institutional roles.</p></div><a class="btn btn-primary" href="/users/new">+ Register staff</a></div>
<section class="panel"><form method="get" action="/users" class="search-row"><input class="form-control" type="search" name="q" value="<?= e($search) ?>" placeholder="Search name/email"><button class="btn btn-primary">Search</button></form><div class="table-scroll"><table class="table table-clean"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Manage</th></tr></thead><tbody><?php foreach($items as $r):?><tr><td><?= e($r['full_name']) ?></td><td><?= e($r['email']) ?></td><td><?= e(ucwords(str_replace('_',' ',$r['role_slug']))) ?></td><td><span class="status-pill <?= $r['account_status']==='active'?'active':'inactive' ?>"><?= e($r['account_status']) ?></span></td><td><?php if($r['role_slug']==='student'):?><a class="btn btn-outline-primary btn-sm" href="/students">Students</a><?php else:?><div class="inline-actions"><a class="btn btn-outline-primary btn-sm" href="/users/edit?id=<?= (int)$r['id'] ?>">Edit</a><form method="post" action="/users/status"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="status" value="<?= $r['account_status']==='active'?'suspended':'active' ?>"><button type="submit" class="btn btn-outline-secondary btn-sm"><?= $r['account_status']==='active'?'Suspend':'Reactivate' ?></button></form></div><?php endif;?></td></tr><?php endforeach; ?></tbody></table></div><?= page_links($page,$total,'/users?q='.rawurlencode($search)) ?></section>
